style.css:
/* WHOLE PAGE BACKGROUND */
body {
  background-color: #222 !important;
  color: white !important;
}

/* SIDEBAR */
div[class*="Root__nav-bar"] {
  background-color: #ff5555 !important; /* red */
}

/* TOP BAR (search, profile) */
div[class*="Root__top-bar"] {
  background-color: #55ff55 !important; /* green */
}

/* MAIN AREA (playlist view, library, etc) */
div[class*="main-view-container"] {
  background-color: #5555ff !important; /* blue */
}

/* PLAYER (bottom music controls) */
div[class*="main-nowPlayingBar"] {
  background-color: #ffaa00 !important; /* orange */
}

/* BUTTONS */
button {
  background-color: #ff55ff !important; /* pink */
  color: white !important;
  border-radius: 8px !important;
}
